'use strict';
const $=id=>document.getElementById(id), catalogue=window.BOOK?.items||[];
let matches=[],position=0,shown=40;
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paragraphs=s=>escapeHTML(s).replace(/\n/g,'<br>');
for(const [id,key] of [['category','category'],['mod','mod']]){for(const value of [...new Set(catalogue.map(e=>e[key]))].filter(Boolean).sort()){const o=document.createElement('option');o.value=o.textContent=value;$(id).append(o)}}
$('total').textContent=catalogue.length.toLocaleString();
const labels={detailed:'Detailed explanation',general:'General item type',pending:'Needs research'};
function setList(){const list=$('results');list.replaceChildren();for(let i=0;i<Math.min(shown,matches.length);i++){const e=matches[i],b=document.createElement('button');b.className='result'+(i===position?' active':'');b.setAttribute('aria-current',i===position?'page':'false');b.innerHTML='<span class="dot" aria-hidden="true"></span><span>'+escapeHTML(e.name)+'<small>'+escapeHTML(e.mod)+'</small></span>';b.onclick=()=>{position=i;render();};list.append(b)}$('more').hidden=shown>=matches.length}
function section(title,body){return body?'<section><h2>'+title+'</h2><p>'+paragraphs(body)+'</p></section>':''}
function render(){const e=matches[position];$('book').hidden=!e;$('empty').hidden=!!e;$('previous').disabled=!e||position===0;$('next').disabled=!e||position>=matches.length-1;$('page-count').textContent=e?`${(position+1).toLocaleString()} / ${matches.length.toLocaleString()}`:'0 items';setList();if(!e)return;
 $('item-name').textContent=e.name;$('mod-label').textContent=e.mod;$('chapter-label').textContent=e.category||'ITEM CATALOGUE';$('category-label').textContent=e.category||'Unsorted';$('summary').textContent=e.summary;$('status').textContent=labels[e.status]||labels.pending;$('status').className='status'+(e.status==='detailed'?'':' pending');$('item-id').textContent=e.id;
 const art=$('item-art');art.textContent='';art.className='';art.style.backgroundPosition='';art.setAttribute('aria-label',e.name+(e.icon===undefined?' — artwork unavailable':''));if(Number.isInteger(e.icon)){art.className='sprite';art.style.backgroundPosition=`-${e.icon%128*96}px -${Math.floor(e.icon/128)*96}px`}else{art.textContent=e.name.slice(0,1)}
 $('detail-content').innerHTML=section('How to use it',e.use)+section('How to get it',e.obtain)+(e.warning?'<section class="warning"><h2>Before you use it</h2><p>'+paragraphs(e.warning)+'</p></section>':'');
 $('pack-note').hidden=!e.packNote;$('pack-note').textContent=e.packNote||'';
 $('evidence-content').innerHTML='<p>'+escapeHTML(e.status==='detailed'?'Written from the local sources below. Exact stats or additional effects are only included when verified.':e.status==='general'?'This is an explanation of the item’s general type. Its individual mod behavior has not been fully verified.':'The item appears in the exported catalogue. A reliable explanation of its behavior is still needed.')+'</p>'+[...new Set(e.sources||[e.source||'kubejs/gacha_items.json'])].map(s=>'<p><code>'+escapeHTML(s)+'</code></p>').join('');
 const hash='#item='+encodeURIComponent(e.id);try{history.replaceState(null,'',hash)}catch{};$('book').classList.remove('turn');void $('book').offsetWidth;$('book').classList.add('turn');
}
function filter(preferred){const query=$('search').value.trim().toLowerCase().split(/\s+/).filter(Boolean);matches=catalogue.filter(e=>(!$('category').value||e.category===$('category').value)&&(!$('mod').value||e.mod===$('mod').value)&&(!$('explained').checked||e.status==='detailed')&&query.every(q=>[e.name,e.id,e.mod,e.summary,e.category].join(' ').toLowerCase().includes(q)));position=Math.max(0,matches.findIndex(e=>e.id===preferred));shown=40;$('result-count').textContent=matches.length.toLocaleString()+' matching '+(matches.length===1?'item':'items');render()}
function turn(delta){const next=position+delta;if(next<0||next>=matches.length)return;position=next;render()}
let debounce; $('search').addEventListener('input',()=>{clearTimeout(debounce);debounce=setTimeout(()=>filter(),120)});for(const id of ['category','mod','explained'])$(id).addEventListener('change',()=>filter());$('more').onclick=()=>{shown+=40;setList()};$('previous').onclick=()=>turn(-1);$('next').onclick=()=>turn(1);$('clear').onclick=()=>{$('search').value=$('category').value=$('mod').value='';$('explained').checked=false;filter()};
document.addEventListener('keydown',e=>{if($('about').open||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='ArrowLeft'){e.preventDefault();turn(-1)}if(e.key==='ArrowRight'){e.preventDefault();turn(1)}});
let touch; $('book').addEventListener('touchstart',e=>{if(e.touches.length===1)touch={x:e.touches[0].clientX,y:e.touches[0].clientY};else touch=null},{passive:true});$('book').addEventListener('touchend',e=>{if(!touch)return;const dx=e.changedTouches[0].clientX-touch.x,dy=e.changedTouches[0].clientY-touch.y;if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)*1.6)turn(dx<0?1:-1);touch=null},{passive:true});$('book').addEventListener('touchcancel',()=>touch=null);
$('about-button').onclick=()=>$('about').showModal();$('close-about').onclick=()=>$('about').close();$('about').addEventListener('click',e=>{if(e.target===$('about')){const b=$('about').getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)$('about').close()}});
const detailed=catalogue.filter(e=>e.status==='detailed').length,general=catalogue.filter(e=>e.status==='general').length;$('coverage').innerHTML=`<p><strong>${catalogue.length.toLocaleString()} items indexed</strong><br>${detailed.toLocaleString()} detailed explanations · ${general.toLocaleString()} general descriptions · ${(catalogue.length-detailed-general).toLocaleString()} still need research.</p>`;
let initial;try{initial=new URLSearchParams(location.hash.slice(1)).get('item')}catch{}filter(initial);
